/* app/site.css — Fightlytics landing.
   Dark only. Token values mirror frontend/src/index.css: a flat off-black background (no grain, no glow orbs),
   and orange is the brand and CTA colour only; red/blue always mean corners.
   Radii: controls 6px, panels 12px. */
:root {
  --bg: #0b0b0c;
  --panel: #0f1012;
  --panel-2: #141518;
  --line: rgba(255, 255, 255, 0.09);
  --line-2: rgba(255, 255, 255, 0.16);
  --ink: #f2f1ee;
  --ink-2: #c9c7c1;
  --mute: #9a9892;
  --accent: #ff4d1c;
  --accent-hover: #ff6a40;
  --accent-on: #190500;
  --red: #ef4444;
  --blue: #60a5fa; /* keep in sync with CORNER in stage.jsx */
  --green: #0ca30c;
  --nav-h: 64px;
  --maxw: 1320px;
  --r-ctl: 6px;
  --r-panel: 12px;
  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  --z-nav: 20;
  --z-skip: 40;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; scroll-padding-top: var(--nav-h); color-scheme: dark; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink-2);
  font: 400 17px/1.6 'Archivo', system-ui, sans-serif;
  font-stretch: 100%;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}
::selection { background: rgba(255, 77, 28, 0.3); color: #fff; }
a { color: inherit; }
.mono { font-family: 'JetBrains Mono', ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; }
.wrap { max-width: var(--maxw); margin: 0 auto; padding: 0 32px; }

.material-symbols-outlined {
  font-family: 'Material Symbols Outlined'; font-weight: normal; font-style: normal; line-height: 1;
  letter-spacing: normal; text-transform: none; display: inline-block; white-space: nowrap; direction: ltr;
  font-feature-settings: 'liga'; -webkit-font-smoothing: antialiased; user-select: none;
}

/* ---------- type ---------- */
.h1, .h2, .h3 { margin: 0; color: var(--ink); font-family: 'Archivo', sans-serif; text-wrap: balance; }
.h1 { font-size: clamp(40px, 4.2vw, 62px); line-height: 0.96; font-weight: 800; font-stretch: 72%; letter-spacing: -0.012em; }
.h2 { font-size: clamp(34px, 3.6vw, 54px); line-height: 1; font-weight: 800; font-stretch: 75%; letter-spacing: -0.01em; }
.h3 { font-size: clamp(28px, 2.5vw, 38px); line-height: 1.04; font-weight: 750; font-stretch: 80%; letter-spacing: -0.01em; }
.lede { margin: 0; font-size: clamp(18px, 1.35vw, 20px); line-height: 1.55; color: var(--ink-2); max-width: 44ch; text-wrap: pretty; }
.body { margin: 0; color: var(--ink-2); max-width: 46ch; text-wrap: pretty; }

/* ---------- controls ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; height: 46px; padding: 0 20px;
  border-radius: var(--r-ctl); background: var(--accent); color: var(--accent-on); border: 0; cursor: pointer;
  font: 650 15.5px/1 'Archivo', sans-serif; font-stretch: 100%; text-decoration: none; white-space: nowrap;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.22);
  transition: background 0.2s, transform 0.2s var(--ease), box-shadow 0.2s;
}
.btn:hover { background: var(--accent-hover); }
.btn:active { transform: translateY(1px); }
.btn.sm { height: 36px; padding: 0 14px; font-size: 14px; }
.link { display: inline-flex; align-items: center; gap: 6px; font-weight: 600; color: var(--ink); text-decoration: none; }
.link .material-symbols-outlined { font-size: 19px; transition: transform 0.25s var(--ease); }
.link:hover .material-symbols-outlined { transform: translateX(3px); }
:focus-visible { outline: 2px solid var(--ink); outline-offset: 3px; border-radius: 4px; }
.skip { position: absolute; left: 16px; top: -60px; z-index: var(--z-skip); background: var(--ink); color: var(--bg); padding: 10px 14px; border-radius: var(--r-ctl); font-weight: 600; }
.skip:focus { top: 12px; }

/* index.html's <noscript> copy, for readers and crawlers without JavaScript */
.noscript { padding-top: 64px; padding-bottom: 64px; }
.noscript .h3 { margin: 48px 0 12px; }
.noscript .lede { margin-top: 20px; }
.noscript ul { padding-left: 1.2em; }

/* ---------- brand lockup (logo.jsx) ---------- */
.brand { display: inline-flex; align-items: center; gap: 10px; }
.brand-word { font-family: 'Bebas Neue', sans-serif; letter-spacing: 0.055em; text-transform: uppercase; line-height: 0.95; color: var(--ink); }
.brand.stack { display: flex; flex-direction: column; align-items: center; gap: 12px; }

/* ---------- nav ---------- */
.nav { position: sticky; top: 0; z-index: var(--z-nav); height: var(--nav-h); background: rgba(11, 11, 12, 0.8); backdrop-filter: blur(16px) saturate(1.4); -webkit-backdrop-filter: blur(16px) saturate(1.4); border-bottom: 1px solid var(--line); }
.nav-in { max-width: var(--maxw); height: 100%; margin: 0 auto; padding: 0 32px; display: flex; align-items: center; gap: 36px; }
.nav-brand { display: flex; text-decoration: none; }
.nav-links { display: flex; gap: 28px; margin-left: auto; }
.nav-links a { font-size: 14px; font-weight: 500; color: var(--mute); text-decoration: none; transition: color 0.2s; }
.nav-links a:hover { color: var(--ink); }
.nav-ctas { display: flex; align-items: center; gap: 20px; }
.nav-signin { font-size: 14px; font-weight: 600; color: var(--ink-2); text-decoration: none; transition: color 0.2s; }
.nav-signin:hover { color: var(--ink); }

/* ---------- waitlist (app.jsx WaitlistForm) ---------- */
.wl { width: 100%; max-width: 460px; }
.wl-form { display: flex; gap: 8px; }
.wl-input {
  flex: 1; min-width: 0; height: 46px; padding: 0 14px; border-radius: var(--r-ctl);
  background: rgba(0, 0, 0, 0.35); border: 1px solid var(--line-2); color: var(--ink);
  font: 500 16px/1 'Archivo', sans-serif; /* 16px keeps iOS from zooming on focus */
  transition: border-color 0.2s;
}
.wl-input::placeholder { color: var(--mute); }
.wl-input:focus { outline: none; border-color: var(--ink-2); }
.wl-form .btn { gap: 8px; }
.btn:disabled { cursor: default; }
.wl-spin { width: 14px; height: 14px; border-radius: 50%; border: 2px solid currentColor; border-right-color: transparent; animation: wl-spin 0.8s linear infinite; }
.wl-err { margin: 10px 0 0; font-size: 14px; font-weight: 500; color: var(--ink); } /* not red: red means the red corner here */
.wl-note { margin: 0; font-size: 14px; color: var(--mute); }
.wl-note a { color: var(--ink); font-weight: 600; text-underline-offset: 3px; }
.wl-out { animation: wl-out 0.2s ease-in forwards; }
.wl-done { display: flex; align-items: center; gap: 16px; text-align: left; max-width: 460px; }
.wl-done > div > * { animation: rise 0.6s var(--ease) both; }
.wl-done > div > :first-child { animation-delay: 0.3s; }
.wl-done > div > :last-child { animation-delay: 0.4s; }
.wl-done-h { margin: 0; font: 750 22px/1.1 'Archivo', sans-serif; font-stretch: 80%; color: var(--ink); }
.wl-done-p { margin: 4px 0 0; font-size: 15px; color: var(--ink-2); }
.wl-email { color: var(--ink); overflow-wrap: anywhere; }
/* success green, never orange (brand/CTA) or red/blue (corners) */
.wl-badge { flex: none; display: inline-flex; border-radius: 50%; stroke: var(--green); animation: wl-pop 0.45s var(--ease) both, wl-ring 0.9s ease-out 0.75s; }
.wl-badge circle, .wl-badge path { stroke-dasharray: 1; stroke-dashoffset: 1; }
.wl-badge circle { animation: wl-draw 0.5s cubic-bezier(0.65, 0, 0.35, 1) 0.05s forwards; }
.wl-badge path { animation: wl-draw 0.3s cubic-bezier(0.65, 0, 0.35, 1) 0.45s forwards; }
@keyframes wl-spin { to { transform: rotate(360deg); } }
@keyframes wl-out { to { opacity: 0; transform: translateY(-6px) scale(0.98); } }
@keyframes wl-draw { to { stroke-dashoffset: 0; } }
@keyframes wl-pop { 0% { transform: scale(0.6); opacity: 0; } 60% { transform: scale(1.08); opacity: 1; } 100% { transform: scale(1); } }
@keyframes wl-ring { 0% { box-shadow: 0 0 0 0 color-mix(in srgb, var(--green) 45%, transparent); } 100% { box-shadow: 0 0 0 14px transparent; } }

/* ---------- story: hero + pipeline steps beside the pinned replay ---------- */
.story { max-width: var(--maxw); margin: 0 auto; padding: 0 32px; display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); column-gap: clamp(32px, 4.5vw, 80px); }
.hero { min-height: calc(100dvh - var(--nav-h)); display: flex; flex-direction: column; justify-content: center; gap: 26px; padding: 40px 0 56px; }
.hero-ctas { display: flex; flex-direction: column; align-items: flex-start; gap: 14px; margin-top: 6px; }
.hero > * { animation: rise 0.9s var(--ease) both; }
.hero > :nth-child(2) { animation-delay: 0.08s; }
.hero > :nth-child(3) { animation-delay: 0.16s; }
@keyframes rise { from { opacity: 0; transform: translateY(18px); } }

.step { min-height: 92dvh; display: flex; flex-direction: column; justify-content: center; gap: 18px; padding: 40px 0; }
.step:last-child { min-height: calc(100dvh - var(--nav-h)); }
.step .h3 { max-width: 15ch; }
.step-note { margin: 4px 0 0; font-size: 15px; color: var(--mute); max-width: 40ch; }
.chips, .vocab > div { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.vocab { display: flex; flex-direction: column; gap: 10px; margin-top: 4px; }
.vocab-k { width: 58px; font-size: 13px; color: var(--mute); }
